#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int smallestDivisor(vector<int>& nums, int limit) {
        int low = 1, high = *max_element(nums.begin(), nums.end());
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long long total = 0;
            for (int x : nums) total += (x + mid - 1) / mid;
            if (total <= limit) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
};

class Solution {
    public int smallestDivisor(int[] nums, int limit) {
        int low = 1, high = 0;
        for (int x : nums) high = Math.max(high, x);
        int ans = high;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            long total = 0;
            for (int x : nums) total += (x + mid - 1) / mid;
            if (total <= limit) {
                ans = mid;
                high = mid - 1;
            } else {
                low = mid + 1;
            }
        }
        return ans;
    }
}

var smallestDivisor = function(nums, limit) {
    let low = 1, high = Math.max(...nums);
    let ans = high;
    while (low <= high) {
        const mid = Math.floor((low + high) / 2);
        let total = 0;
        for (const x of nums) total += Math.floor((x + mid - 1) / mid);
        if (total <= limit) {
            ans = mid;
            high = mid - 1;
        } else {
            low = mid + 1;
        }
    }
    return ans;
};
